//! The four list operations, served a page at a time.
//!
//! [`crate::pagination`] decides what a page *is* — which items, which cursor
//! comes next, which cursors are valid. This is the handler's side: read the
//! request's cursor, refuse one this server never issued, and build the
//! result through rmcp's own constructor so `resultType` and the caching
//! hints stay rmcp's business (see `list_resources` in the parent module).
//!
//! `tools/list` and `prompts/list` used to be generated by rmcp's
//! `#[tool_handler]` and `#[prompt_handler]` macros, which list every route in
//! one page and cannot be told otherwise. `#[tool_handler]` honours a
//! hand-written `list_tools`; `#[prompt_handler]` overwrites a hand-written
//! `list_prompts` outright, so the prompt half of that macro is replaced here
//! entirely — `get_prompt` included, as the same one-line delegation to the
//! prompt router that the macro expands to. All four listings now take the
//! same caching hints as every other cacheable result this server builds.

use rmcp::RoleServer;
use rmcp::handler::server::prompt::PromptContext;
use rmcp::model::{
    ErrorData as McpError, GetPromptRequestParams, GetPromptResponse, ListPromptsResult,
    ListResourceTemplatesResult, ListResourcesResult, ListToolsResult, PaginatedRequestParams,
};
use rmcp::service::RequestContext;

use super::EverythingServer;
use crate::pagination::{Listing, Page};
use crate::{prompts, resources, tools};

/// The page `request` asked for, out of `items`.
fn requested<T>(
    listing: Listing,
    items: Vec<T>,
    page_of: impl Fn(&T) -> usize,
    request: Option<&PaginatedRequestParams>,
) -> Result<Page<T>, McpError> {
    let cursor = request.and_then(|request| request.cursor.as_deref());
    let page = listing.requested_page(cursor)?;
    Ok(listing.page(items, page_of, page))
}

impl EverythingServer {
    /// One page of `tools/list`.
    pub(super) fn tools_page(
        &self,
        request: Option<&PaginatedRequestParams>,
    ) -> Result<ListToolsResult, McpError> {
        let page = requested(
            Listing::Tools,
            self.tool_router.list_all(),
            tools::page_of,
            request,
        )?;
        let mut result = ListToolsResult::with_all_items(page.items);
        result.next_cursor = page.next_cursor;
        Ok(self.cached(result))
    }

    /// One page of `prompts/list`.
    pub(super) fn prompts_page(
        &self,
        request: Option<&PaginatedRequestParams>,
    ) -> Result<ListPromptsResult, McpError> {
        let page = requested(
            Listing::Prompts,
            self.prompt_router.list_all(),
            prompts::page_of,
            request,
        )?;
        let mut result = ListPromptsResult::with_all_items(page.items);
        result.next_cursor = page.next_cursor;
        Ok(self.cached(result))
    }

    /// One page of `resources/list`.
    pub(super) fn resources_page(
        &self,
        request: Option<&PaginatedRequestParams>,
    ) -> Result<ListResourcesResult, McpError> {
        let page = requested(
            Listing::Resources,
            resources::catalog(),
            resources::page_of,
            request,
        )?;
        let mut result = ListResourcesResult::with_all_items(page.items);
        result.next_cursor = page.next_cursor;
        Ok(self.cached(result))
    }

    /// One page of `resources/templates/list`.
    pub(super) fn templates_page(
        &self,
        request: Option<&PaginatedRequestParams>,
    ) -> Result<ListResourceTemplatesResult, McpError> {
        let page = requested(
            Listing::ResourceTemplates,
            resources::templates(),
            resources::template_page_of,
            request,
        )?;
        let mut result = ListResourceTemplatesResult::with_all_items(page.items);
        result.next_cursor = page.next_cursor;
        Ok(self.cached(result))
    }

    /// `prompts/get`, exactly as `#[prompt_handler]` would expand it.
    pub(super) async fn prompt(
        &self,
        request: GetPromptRequestParams,
        context: RequestContext<RoleServer>,
    ) -> Result<GetPromptResponse, McpError> {
        let prompt_context = PromptContext::new(self, request.name, request.arguments, context);
        self.prompt_router.get_prompt(prompt_context).await
    }
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use rmcp::model::{CacheScope, ErrorCode};

    use super::*;
    use crate::server::ServedRevision;

    fn at(cursor: Option<String>) -> PaginatedRequestParams {
        PaginatedRequestParams::default().with_cursor(cursor)
    }

    #[test]
    fn every_listing_round_trips_its_cursor_to_a_second_page_and_ends() {
        for revision in [ServedRevision::V2025_11_25, ServedRevision::V2026_07_28] {
            let server = EverythingServer::serving(revision);
            let first = server.tools_page(None).unwrap();
            let second = server.tools_page(Some(&at(first.next_cursor))).unwrap();
            assert!(!second.tools.is_empty(), "{revision:?}: tools page 2");
            assert_eq!(second.next_cursor, None);

            let first = server.prompts_page(None).unwrap();
            let second = server.prompts_page(Some(&at(first.next_cursor))).unwrap();
            assert_eq!(second.prompts.len(), 1);
            assert_eq!(second.next_cursor, None);

            let first = server.resources_page(None).unwrap();
            let second = server.resources_page(Some(&at(first.next_cursor))).unwrap();
            assert_eq!(second.resources[0].uri, resources::ANNOTATED_URI);
            assert_eq!(second.next_cursor, None);

            let first = server.templates_page(None).unwrap();
            let second = server.templates_page(Some(&at(first.next_cursor))).unwrap();
            assert_eq!(
                second.resource_templates[0].uri_template,
                resources::ANNOTATED_TEMPLATE_URI
            );
            assert_eq!(second.next_cursor, None);
        }
    }

    #[test]
    fn the_first_pages_are_exactly_the_suites_catalogue() {
        let server = EverythingServer::new();
        let prompts: Vec<String> = server
            .prompts_page(None)
            .unwrap()
            .prompts
            .into_iter()
            .map(|prompt| prompt.name)
            .collect();
        assert_eq!(
            prompts,
            [
                "test_prompt_with_arguments",
                "test_prompt_with_embedded_resource",
                "test_prompt_with_image",
                "test_simple_prompt",
            ]
        );
        let tools = server.tools_page(None).unwrap().tools;
        assert!(tools.iter().all(|tool| tools::page_of(tool) == 0));
        assert!(tools.iter().any(|tool| tool.name == "test_simple_text"));
        assert_eq!(server.resources_page(None).unwrap().resources.len(), 2);
        assert_eq!(
            server
                .templates_page(None)
                .unwrap()
                .resource_templates
                .len(),
            1
        );
    }

    #[test]
    fn a_cursor_never_issued_is_refused_with_invalid_params() {
        let server = EverythingServer::new();
        let fabricated = at(Some("fabricated".to_owned()));
        let bogus = Some(&fabricated);
        // A cursor one listing issued is not valid for another.
        let foreign = at(server.tools_page(None).unwrap().next_cursor);
        for error in [
            server.tools_page(bogus).unwrap_err(),
            server.prompts_page(bogus).unwrap_err(),
            server.resources_page(bogus).unwrap_err(),
            server.templates_page(bogus).unwrap_err(),
            server.prompts_page(Some(&foreign)).unwrap_err(),
        ] {
            assert_eq!(error.code, ErrorCode::INVALID_PARAMS);
        }
    }

    #[test]
    fn every_page_of_a_listing_carries_the_same_cache_scope() {
        // CACH-015: "Servers MUST apply the same `cacheScope` to all response
        // pages for a given list request."
        let server = EverythingServer::serving(ServedRevision::V2026_07_28);
        let first = server.resources_page(None).unwrap();
        let second = server
            .resources_page(Some(&at(first.next_cursor.clone())))
            .unwrap();
        assert_eq!(first.cache_scope, Some(CacheScope::Public));
        assert_eq!(first.cache_scope, second.cache_scope);
        let first = server.tools_page(None).unwrap();
        let second = server
            .tools_page(Some(&at(first.next_cursor.clone())))
            .unwrap();
        assert_eq!(first.cache_scope, second.cache_scope);
    }
}
